const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry definitions
  const mesquiteFlat = ee.Geometry.Point([-117.08, 36.6]).buffer(1000);
  const panamintMountains = ee.Geometry.Point([-117.2, 36.1]).buffer(1000);

  const date = '2013-06-30';

  // 2. Data acquisition - Landsat 8 Collection 2 Tier 1
  const landsat8 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
    .filterDate(date, ee.Date(date).advance(1, 'day'));

  // 3. Function to get LST from Landsat 8 (ST_B10 band in Kelvin)
  function getLST(img) {
    // Apply scaling factor for LST: 0.00341802 * ST_B10 + 149.0 - 273.15 to convert to Celsius
    return img.select('ST_B10')
      .multiply(0.00341802)
      .add(149.0)
      .subtract(273.15)
      .updateMask(img.select('ST_B10').gt(0));
  }

  // 4. Get image for each location
  const imgMesquite = landsat8.filterBounds(mesquiteFlat).first();
  const imgPanamint = landsat8.filterBounds(panamintMountains).first();

  // Check if images exist
  const countMesquite = imgMesquite ? 1 : 0;
  const countPanamint = imgPanamint ? 1 : 0;

  console.log(`Mesquite Flat images: ${countMesquite}`);
  console.log(`Panamint Mountains images: ${countPanamint}`);

  if (countMesquite === 0 || countPanamint === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // 5. Calculate mean LST for each location
  const reducer = ee.Reducer.mean();
  const scale = 1000;

  const lstMesquite = getLST(imgMesquite);
  const lstPanamint = getLST(imgPanamint);

  const statsMesquite = lstMesquite.reduceRegion({
    reducer: reducer,
    geometry: mesquiteFlat,
    scale: scale,
    maxPixels: 1e9
  });

  const statsPanamint = lstPanamint.reduceRegion({
    reducer: reducer,
    geometry: panamintMountains,
    scale: scale,
    maxPixels: 1e9
  });

  const meanMesquite = statsMesquite.get('ST_B10').getInfo();
  const meanPanamint = statsPanamint.get('ST_B10').getInfo();

  // 6. Check for valid pixels
  const countReducer = ee.Reducer.count();

  const countStatsMesquite = lstMesquite.reduceRegion({
    reducer: countReducer,
    geometry: mesquiteFlat,
    scale: scale,
    maxPixels: 1e9
  });

  const countStatsPanamint = lstPanamint.reduceRegion({
    reducer: countReducer,
    geometry: panamintMountains,
    scale: scale,
    maxPixels: 1e9
  });

  const pixelCountMesquite = countStatsMesquite.get('ST_B10').getInfo();
  const pixelCountPanamint = countStatsPanamint.get('ST_B10').getInfo();

  console.log(`Mesquite LST: ${meanMesquite?.toFixed(1)}°C (pixels: ${pixelCountMesquite})`);
  console.log(`Panamint LST: ${meanPanamint?.toFixed(1)}°C (pixels: ${pixelCountPanamint})`);

  // 7. Validation checks
  if (pixelCountMesquite === 0 || pixelCountPanamint === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  if (meanMesquite === null || meanPanamint === null || 
      isNaN(meanMesquite) || isNaN(meanPanamint)) {
    console.log("<answer>C3</answer>");
    return;
  }

  // Validate reasonable temperature range (-50 to 70°C for desert areas)
  if (meanMesquite < -50 || meanMesquite > 70 || 
      meanPanamint < -50 || meanPanamint > 70) {
    console.log("<answer>C3</answer>");
    return;
  }

  // 8. Final comparison
  if (meanMesquite > meanPanamint) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
